"use strict";

// API contract tests — pin the HTTP response SHAPES that public/app.js consumes.
//
// A contract test drives the REAL route (in-process, against the exported `app`)
// and asserts field names + types + nesting — never concrete values. Values
// change every time data/*.json is regenerated by Suggested Updates; the shape is
// what the frontend depends on and what an optimisation must preserve.
//
// This file is the safety net for the "optimise without breaking" work: it proves
// "behaviour unchanged" so dedupe / dead-code / module-split steps can't silently
// rename a field or drop a key that the frontend reads.
//
// Mechanics: server.js exports `app` and guards `listen()` behind
// `require.main === module`, so `require("../server")` never binds a port. We
// drive routes with Node's built-in http + fetch against 127.0.0.1:0 — no new
// dependencies, no external socket. The reference for every assertion below is
// docs/api-contract.md.

process.env.SCAN_MODEL_MIN_GAP_MS = "50";      // keep any scan pacing fast
process.env.TAVILY_API_KEY = "contract-test-key"; // enable /api/search success path

const { test, before, after } = require("node:test");
const assert = require("node:assert");
const http = require("http");

const srv = require("../server");
const app = srv.app;
const realFetch = globalThis.fetch; // saved before any stubbing below

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------
const isStr = (v) => typeof v === "string";
const isNum = (v) => typeof v === "number" && Number.isFinite(v);
const isBool = (v) => typeof v === "boolean";
const isObj = (v) => v !== null && typeof v === "object" && !Array.isArray(v);
const isArr = Array.isArray;

const NEWS_SOURCES = ["Google News RSS", "Bing News RSS", "Cached"];

function startServer() {
  return new Promise((resolve) => {
    const s = http.createServer(app);
    s.listen(0, "127.0.0.1", () => resolve(s));
  });
}
function closeServer(server) {
  return new Promise((resolve) => server.close(resolve));
}

// Requests use `realFetch` (not globalThis.fetch) so stubbing globalThis.fetch in
// the network-route tests never breaks the harness's own HTTP call.
async function request(server, method, path, body) {
  const port = server.address().port;
  const opts = { method, headers: { accept: "application/json" } };
  if (body !== undefined) {
    opts.headers["content-type"] = "application/json";
    opts.body = JSON.stringify(body);
  }
  const res = await realFetch(`http://127.0.0.1:${port}${path}`, opts);
  const text = await res.text();
  let json = null;
  try { json = JSON.parse(text); } catch { /* non-JSON body */ }
  return { status: res.status, contentType: res.headers.get("content-type") || "", body: json, text };
}

function stubFetch(handler) {
  const original = globalThis.fetch;
  globalThis.fetch = handler;
  return () => { globalThis.fetch = original; };
}

// Shared news envelope (docs/api-contract.md §2 "GET /api/news").
function assertNewsEnvelope(body) {
  assert.strictEqual(body.success, true);
  assert.ok(isNum(body.count), "count must be a number");
  assert.ok(isArr(body.articles), "articles must be an array");
  assert.ok(body.articles.length > 0, "articles must be non-empty");
  assert.ok(isArr(body.topics), "topics must be an array");
  assert.ok(isArr(body.monitoredCompetitors), "monitoredCompetitors must be an array");
  for (const c of body.monitoredCompetitors) {
    assert.ok(isStr(c.id), "competitor.id must be a string");
    assert.ok(isStr(c.name), "competitor.name must be a string");
    assert.ok(isBool(c.custom), "competitor.custom must be a boolean");
  }
  assert.ok(isStr(body.searchedAt), "searchedAt must be a string");
  assert.ok(isBool(body.live), "live must be a boolean");
  assert.ok(isBool(body.cached), "cached must be a boolean");
  assert.strictEqual(body.cached, !body.live, "cached must be the inverse of live");
  assert.ok(isStr(body.source) && NEWS_SOURCES.includes(body.source),
    `source must be one of ${NEWS_SOURCES.join(" | ")}`);
}

// Shared article element shape (docs/api-contract.md §3).
function assertArticleShape(a) {
  assert.ok(isStr(a.title) && a.title.length > 0, "article.title must be a non-empty string");
  assert.ok(isStr(a.url) && /^https?:\/\//.test(a.url), "article.url must be an http(s) string");
  assert.ok(isStr(a.sourceName), "article.sourceName must be a string");
  assert.ok(a.publishedAt === null || isStr(a.publishedAt),
    "article.publishedAt must be a string or null");
}

let server;
before(async () => { server = await startServer(); });
after(async () => { if (server) await closeServer(server); });

