test("GET /api/news returns the news envelope (live Google RSS)", async () => {
  const rss = googleNewsRss([
    { title: "EU AI Act final vote", url: "https://example.com/ai-act-1", desc: "Lawmakers approve the act.", pubDate: "Mon, 18 Aug 2026 12:00:00 GMT", source: "Example News" },
    { title: "AI in game development", url: "https://example.com/ai-gaming-2", desc: "Studios adopt AI tooling.", pubDate: null, source: "Example Tech" },
  ]);
  const restore = stubFetch(async (url) => {
    if (String(url).includes("news.google.com")) {
      return {
        ok: true, status: 200, url: String(url),
        headers: { get: (h) => (h.toLowerCase() === "content-type" ? "application/rss+xml" : null) },
        text: async () => rss,
      };
    }
    throw new Error("network down");
  });
  try {
    // ?refresh bypasses the serve-cache (incl. the boot pre-warm) so this test
    // exercises the live Google path directly.
    const { status, body } = await request(server, "GET", "/api/news?refresh=1");
    assert.strictEqual(status, 200);
    assertNewsEnvelope(body);
    assert.strictEqual(body.live, true);
    assert.strictEqual(body.cached, false);
    assert.strictEqual(body.source, "Google News RSS");
    // Both publishedAt branches pinned: one string, one null.
    assert.ok(body.articles.some((a) => isStr(a.publishedAt)), "one article has a date");
    assert.ok(body.articles.some((a) => a.publishedAt === null), "one article has a null date");
    for (const a of body.articles) assertArticleShape(a);
  } finally {
    restore();
  }
});

// --- Step 2c: serve-from-cache + ?refresh bypass ---------------------------------

// Benign response for non-RSS URLs (Tavily / article-host enrichment fetches)
// so the fire-and-forget subhead warming never throws. Only news.google.com
// fetches count toward `newsFetches`, isolating the fan-out from enrichment.
function benignNonNews() {
  return {
    ok: true, status: 200, url: "https://example.com/x",
    headers: { get: () => "text/html" },
    text: async () => "<html><head><meta property=\"og:description\" content=\"lead\"></head><body>lead</body></html>",
  };
}

test("GET /api/news serves from cache on repeat (no extra live fan-out)", async () => {
  let newsFetches = 0;
  const restore = stubFetch(async (url) => {
    if (String(url).includes("news.google.com")) {
      newsFetches++;
      return {
        ok: true, status: 200, url: String(url),
        headers: { get: (h) => (h.toLowerCase() === "content-type" ? "application/rss+xml" : null) },
        text: async () => googleNewsRss([
          { title: "Cacheable article", url: "https://example.com/cache-1", desc: "Cache me.", pubDate: "Mon, 18 Aug 2026 12:00:00 GMT", source: "Example News" },
        ]),
      };
    }
    return benignNonNews();
  });
  try {
    // Force a live fetch first to populate the cache with known data.
    const r1 = await request(server, "GET", "/api/news?refresh=1");
    assert.strictEqual(r1.status, 200);
    assertNewsEnvelope(r1.body);
    const afterPopulate = newsFetches;
    assert.ok(afterPopulate >= 1, "refresh must trigger a live fan-out");
    // A plain call must now serve from cache without another news fan-out.
    const r2 = await request(server, "GET", "/api/news");
    assert.strictEqual(r2.status, 200);
    assertNewsEnvelope(r2.body);
    assert.strictEqual(newsFetches, afterPopulate, "repeat /api/news should serve from cache");
  } finally {
    restore();
  }
});

test("GET /api/news?refresh forces a fresh fan-out each time", async () => {
  let newsFetches = 0;
  const restore = stubFetch(async (url) => {
    if (String(url).includes("news.google.com")) {
      newsFetches++;
      return {
        ok: true, status: 200, url: String(url),
        headers: { get: (h) => (h.toLowerCase() === "content-type" ? "application/rss+xml" : null) },
        text: async () => googleNewsRss([
          { title: "Refreshable article", url: "https://example.com/refresh-1", desc: "Fresh.", pubDate: "Mon, 18 Aug 2026 12:00:00 GMT", source: "Example News" },
        ]),
      };
    }
    return benignNonNews();
  });
  try {
    const r1 = await request(server, "GET", "/api/news?refresh=1");
    assert.strictEqual(r1.status, 200);
    const after1 = newsFetches;
    const r2 = await request(server, "GET", "/api/news?refresh=2");
    assert.strictEqual(r2.status, 200);
    // Each ?refresh runs a full live fan-out; the serve-cache is bypassed, so
    // the total is exactly two fan-outs (not one + a cached serve).
    assert.strictEqual(newsFetches, after1 * 2, "each ?refresh forces a fresh fan-out (no serve-cache)");
  } finally {
    restore();
  }
});

test("GET /api/news falls back to Bing when Google returns empty (Track 1 race)", async () => {
  // Force a Google block (empty feed) and a working Bing feed. With ?refresh the
  // serve-cache is bypassed so the live fan-out runs; both fan-outs race and the
  // empty Google result yields to Bing. Unwrapped publisher URLs prove Bing
  // parsing + the apiclick.aspx unwrap both work.
  const restore = stubFetch(async (url) => {
    if (String(url).includes("news.google.com")) {
      return {
        ok: true, status: 200, url: String(url),
        headers: { get: (h) => (h.toLowerCase() === "content-type" ? "application/rss+xml" : null) },
        text: async () => googleNewsRss([]),
      };
    }
    if (String(url).includes("bing.com")) {
      return {
        ok: true, status: 200, url: String(url),
        headers: { get: (h) => (h.toLowerCase() === "content-type" ? "application/rss+xml" : null) },
        text: async () => bingNewsRss([
          { title: "Bing-sourced AI gaming story", url: "https://example.com/bing-1", desc: "From Bing.", pubDate: "Mon, 18 Aug 2026 12:00:00 GMT", source: "Example News" },
        ]),
      };
    }
    return benignNonNews();
  });
  try {
    const { status, body } = await request(server, "GET", "/api/news?refresh=1");
    assert.strictEqual(status, 200);
    assertNewsEnvelope(body);
    assert.strictEqual(body.source, "Bing News RSS", "Bing fallback used when Google empty");
    assert.ok(body.articles.length > 0, "Bing articles present");
    assert.ok(body.articles.every((a) => !String(a.url).includes("bing.com/news/apiclick")),
      "Bing redirector links are unwrapped to direct publisher URLs");
    for (const a of body.articles) assertArticleShape(a);
  } finally {
    restore();
  }
});

// Thread B — SSE live-update stream. Asserts the endpoint opens a proper
// text/event-stream and pushes at least one frame, then disconnects cleanly so
// the test harness doesn't hang or leak an open socket.
test("GET /api/news/stream opens an SSE stream (text/event-stream)", async () => {
  const port = server.address().port;
  const controller = new AbortController();
  const res = await realFetch(`http://127.0.0.1:${port}/api/news/stream`, {
    headers: { accept: "text/event-stream" },
    signal: controller.signal,
  });
  try {
    assert.strictEqual(res.status, 200, "SSE endpoint must return 200");
    assert.match(res.headers.get("content-type") || "", /text\/event-stream/,
      "content-type must be text/event-stream");
    // Read until we receive at least one frame (server writes ": connected" on open).
    const reader = res.body.getReader();
    const deadline = Date.now() + 5000;
    let received = "";
    while (Date.now() < deadline) {
      const { value, done } = await reader.read();
      if (done) break;
      received += Buffer.from(value).toString("utf8");
      if (received.includes("\n\n")) break;
    }
    assert.ok(received.length > 0, "expected at least one SSE frame from the stream");
  } finally {
    controller.abort();
    // Let the server's req 'close' cleanup run so the socket is gone before the
    // after() hook closes the server.
    await new Promise((r) => setTimeout(r, 50));
  }
});
